//! 📨️ Actual original controller dispatches required references through its retained body owner.
use super::*;
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcComplexType};
fn neutral_value(input:&serde_json::Value)->IfcValue{match input["kind"].as_str().unwrap(){"string"=>IfcValue::String(input["value"].as_str().unwrap().into()),"reference"=>IfcValue::Reference(input["value"].as_str().unwrap().parse().unwrap()),"enum"=>IfcValue::Enum(input["value"].as_str().unwrap().into()),"real"=>IfcValue::Real(f64::from_bits(input["value"]["bits"].as_str().unwrap().parse().unwrap())),"unset"=>IfcValue::Unset,_=>panic!("unhandled actual controller fixture scalar")}}
fn neutral_entity(input:&serde_json::Value,id:u64)->IfcEntity{IfcEntity{id,name:input["name"].as_str().unwrap().into(),args:input["args"].as_array().unwrap().iter().map(neutral_value).collect(),complex:input["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(neutral_value).collect()}).collect()}}
#[test]
fn required_type_controller_denied_axes_and_producer_swap_leave_original_request_stationary(){
    let law:serde_json::Value=serde_json::from_str(include_str!("guided-type-cases.json")).unwrap();let args=serde_json::json!({"path":law["path"],"value":{"$ifcType":law["target"],"$ifcInputs":[]}});let mut request=staged_request(&args);request.token.action=law["action"].as_str().unwrap().into();let mut donor=Some(request);let view=staged_view();let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();
    for axis in 0..5{let stock=staged_grant();let grant=match axis{0=>RetainedCloneGrant{maximum_items:0,..stock},1=>RetainedCloneGrant{maximum_copy_bytes:0,..stock},2=>RetainedCloneGrant{maximum_capacity_bytes:0,..stock},3=>RetainedCloneGrant{maximum_depth:0,..stock},_=>stock};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(grant,if axis==4{0}else{1000},|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)));assert!(result.unwrap().is_none());assert!(donor.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
    assert!(caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_none());donor.as_mut().unwrap().token.action=APPLY_TEMPLATE_ACTION.into();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)));assert!(result.is_err());assert!(donor.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.cancel().cancel_now();retire_staged(&mut caller,&mut donor);retire_staged(&mut caller,&mut Some(work));caller.finish();
}
#[test]
fn required_type_input_uses_actual_donated_controller_with_editable_ready_and_incomplete_text(){
    use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};use semio_framework_ui_contract::{Component,ContainerRole,OriginalBuiltTreeRetirement};
    let law:serde_json::Value=serde_json::from_str(include_str!("guided-type-cases.json")).unwrap();let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/primary-remap.json")).unwrap();
    let mut entities=vec![neutral_entity(&fixture["sources"][law["source"].as_str().unwrap()],1)];entities.extend(fixture["tail"].as_array().unwrap().iter().filter(|row|matches!(row["id"].as_str(),Some("6"|"7"))).map(|row|neutral_entity(row,row["id"].as_str().unwrap().parse().unwrap())));let snapshot=std::sync::Arc::new(IfcSnapshot{entities,..Default::default()});let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();
    for row in law["cases"].as_array().unwrap(){
        let inputs=if row["draft"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":law["index"],"value":{"kind":"reference","value":row["draft"]}}])};let mut args=serde_json::json!({"path":law["path"],"value":{"$ifcType":law["target"],"$ifcInputs":inputs}});if row["name"]=="missing-inputs"{args["value"].as_object_mut().unwrap().remove("$ifcInputs");}else if row["name"]=="null-inputs"{args["value"]["$ifcInputs"]=serde_json::Value::Null;}let mut request=staged_request(&args);request.token.action=law["action"].as_str().unwrap().into();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:if row["name"]=="wrong-revision"{[1;32]}else{[0;32]},mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-type-source",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();let mut donor=Some(request);let mut received=false;
        for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){received=true;break;}}assert!(received&&donor.is_none());let mut output=None;let mut refusal=None;
        for _ in 0..100000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(error)=>{refusal=Some(error);break;}}}
        if !row["output"].as_bool().unwrap(){assert!(output.is_none()&&refusal.is_some());retire_staged(&mut caller,&mut refusal);}else{let tree=output.take().expect("original type guidance must complete a body");let Component::Container(form)=&tree.root.component else{panic!("missing type form")};assert_eq!(form.role,ContainerRole::Form);assert_eq!(tree.root.children.len(),2);let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("missing original type status")};let status=serde_json::to_value(&status.props).unwrap();assert_eq!(status["ready"],row["ready"]);let field=tree.root.children.get(1).unwrap();let input=field.children.get(0).unwrap();let Component::Input(props)=&input.component else{panic!("missing editable required reference")};assert_eq!(props.value.as_ref(),row["draft"].as_str().unwrap_or(""));assert!(!input.bindings.is_empty());let binding=serde_json::to_value(input.bindings.get(0).unwrap()).unwrap();assert_eq!(binding["action"]["scope"],IFC4X3_CONTROLLER);assert_eq!(binding["action"]["name"],semio_framework_plugin::action_staging::STAGED_FORM_EVENT_ACTION);assert_eq!(binding["args"]["token"]["action"],law["action"]);let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..100000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());}
        caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));caller.finish();
    }
    assert!(!crate::templates::application::work::staging_native::NATIVE_PREPARED_TEMPLATE_MOUNTED);assert!(!crate::templates::application::work::NATIVE_TEMPLATE_SEMANTIC_ADMISSION);
}
